// src/utils/OutputOptions.js

const MAX_EXPORT_SIZE = 8192;
const MAP_TYPES = ["color", "height", "normal", "roughness", "alpha", "emissive"];

function clampOutputSize(value, fallback = 512) {
  const number = Math.round(Number(value));
  if (!Number.isFinite(number)) return fallback;
  return Math.min(MAX_EXPORT_SIZE, Math.max(1, number));
}

function applyOutputOptions(canvas, options = {}) {
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  const source = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const data = source.data;
  const background = hexToRgb(options.backgroundColor || "#050606");
  const transparent = Boolean(options.transparentNoise);

  for (let i = 0; i < data.length; i += 4) {
    const alpha = data[i + 3] / 255;
    const luminance = (data[i] * 0.2126 + data[i + 1] * 0.7152 + data[i + 2] * 0.0722) / 255;

    if (transparent) {
      data[i + 3] = Math.round(luminance * 255);
    } else {
      data[i] = Math.round(data[i] * alpha + background[0] * (1 - alpha));
      data[i + 1] = Math.round(data[i + 1] * alpha + background[1] * (1 - alpha));
      data[i + 2] = Math.round(data[i + 2] * alpha + background[2] * (1 - alpha));
      data[i + 3] = 255;
    }
  }

  ctx.putImageData(source, 0, 0);
}

function luminanceAt(data, index) {
  return (data[index] * 0.2126 + data[index + 1] * 0.7152 + data[index + 2] * 0.0722) / 255;
}

function setGray(data, index, value) {
  const gray = Math.round(Math.min(1, Math.max(0, value)) * 255);
  data[index] = gray;
  data[index + 1] = gray;
  data[index + 2] = gray;
  data[index + 3] = 255;
}

function isEmissiveGenerator(generatorId = "") {
  return /fire|flame|lava|lightning|electric|tesla|shield|field|portal|laser|beam|magic|rune|rift|glow|light|volcano/.test(generatorId);
}

function applyTileableBlend(canvas, options = {}) {
  if (!options.tileable) return;
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  const image = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const data = image.data;
  const { width, height } = canvas;
  const edge = Math.max(2, Math.round(Math.min(width, height) * 0.08));
  const copy = new Uint8ClampedArray(data);

  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const leftWeight = x < edge ? (edge - x) / edge : 0;
      const rightWeight = x >= width - edge ? (x - (width - edge - 1)) / edge : 0;
      const topWeight = y < edge ? (edge - y) / edge : 0;
      const bottomWeight = y >= height - edge ? (y - (height - edge - 1)) / edge : 0;
      const weight = Math.max(leftWeight, rightWeight, topWeight, bottomWeight);
      if (!weight) continue;
      const sourceIndex = (y * width + x) * 4;
      const wrapX = leftWeight ? width - edge + x : rightWeight ? x - width + edge : x;
      const wrapY = topWeight ? height - edge + y : bottomWeight ? y - height + edge : y;
      const wrapIndex = ((Math.max(0, Math.min(height - 1, wrapY)) * width) + Math.max(0, Math.min(width - 1, wrapX))) * 4;
      for (let c = 0; c < 4; c += 1) {
        data[sourceIndex + c] = Math.round(copy[sourceIndex + c] * (1 - weight) + copy[wrapIndex + c] * weight);
      }
    }
  }

  for (let y = 0; y < height; y += 1) {
    const left = (y * width) * 4;
    const right = (y * width + width - 1) * 4;
    for (let c = 0; c < 4; c += 1) {
      const avg = Math.round((data[left + c] + data[right + c]) * 0.5);
      data[left + c] = avg;
      data[right + c] = avg;
    }
  }
  for (let x = 0; x < width; x += 1) {
    const top = x * 4;
    const bottom = ((height - 1) * width + x) * 4;
    for (let c = 0; c < 4; c += 1) {
      const avg = Math.round((data[top + c] + data[bottom + c]) * 0.5);
      data[top + c] = avg;
      data[bottom + c] = avg;
    }
  }

  ctx.putImageData(image, 0, 0);
}

function buildDerivedMap(canvas, mapType = "color", options = {}) {
  if (mapType === "color") return;
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  const image = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const data = image.data;
  const source = new Uint8ClampedArray(data);
  const { width, height } = canvas;

  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const index = (y * width + x) * 4;
      const lum = luminanceAt(source, index);
      if (mapType === "height") {
        setGray(data, index, lum);
      } else if (mapType === "roughness") {
        const rough = options.generatorId && isEmissiveGenerator(options.generatorId) ? 1 - lum * 0.55 : 0.35 + (1 - lum) * 0.6;
        setGray(data, index, rough);
      } else if (mapType === "alpha") {
        setGray(data, index, source[index + 3] / 255 || lum);
      } else if (mapType === "emissive") {
        const value = isEmissiveGenerator(options.generatorId) ? Math.max(0, (lum - 0.45) / 0.55) : 0;
        data[index] = Math.round(source[index] * value);
        data[index + 1] = Math.round(source[index + 1] * value);
        data[index + 2] = Math.round(source[index + 2] * value);
        data[index + 3] = 255;
      } else if (mapType === "normal") {
        const xl = (y * width + ((x - 1 + width) % width)) * 4;
        const xr = (y * width + ((x + 1) % width)) * 4;
        const yu = (((y - 1 + height) % height) * width + x) * 4;
        const yd = (((y + 1) % height) * width + x) * 4;
        const dx = luminanceAt(source, xl) - luminanceAt(source, xr);
        const dy = luminanceAt(source, yu) - luminanceAt(source, yd);
        const strength = 3.2;
        const nx = dx * strength;
        const ny = dy * strength;
        const nz = 1;
        const length = Math.sqrt(nx * nx + ny * ny + nz * nz) || 1;
        data[index] = Math.round((nx / length * 0.5 + 0.5) * 255);
        data[index + 1] = Math.round((ny / length * 0.5 + 0.5) * 255);
        data[index + 2] = Math.round((nz / length * 0.5 + 0.5) * 255);
        data[index + 3] = 255;
      }
    }
  }

  ctx.putImageData(image, 0, 0);
}


// src/utils/ImageExport.js

function renderTextureCanvas(generator, params, output, mapType = "color") {
  const canvas = document.createElement("canvas");
  canvas.width = clampOutputSize(output.width);
  canvas.height = clampOutputSize(output.height);
  generator.generate(canvas, params, { time: 0, exporting: true, mapType, tileable: output.tileable });
  applyTileableBlend(canvas, output);
  applyOutputOptions(canvas, output);
  buildDerivedMap(canvas, mapType, { generatorId: generator.id });
  return canvas;
}

function canvasToBlob(canvas, mimeType) {
  return new Promise((resolve) => {
    canvas.toBlob((blob) => resolve(blob), mimeType, 0.94);
  });
}

function exportTexture(generator, params, output, mimeType, mapType = "color") {
  const canvas = renderTextureCanvas(generator, params, output, mapType);
  const extension = mimeType === "image/webp" ? "webp" : "png";
  const link = document.createElement("a");
  link.download = `${generator.id}-${mapType}-${canvas.width}x${canvas.height}-${params.Seed || "seed"}.${extension}`;
  link.href = canvas.toDataURL(mimeType, 0.94);
  link.click();
}

async function createTextureBlob(generator, params, output, mimeType, mapType = "color") {
  return canvasToBlob(renderTextureCanvas(generator, params, output, mapType), mimeType);
}

async function exportTexturePack(generator, params, output, mimeType, onProgress = () => {}) {
  const maps = generator.getMeta?.().supportedMaps || MAP_TYPES;
  const width = clampOutputSize(output.width);
  const height = clampOutputSize(output.height);
  const extension = mimeType === "image/webp" ? "webp" : "png";
  const entries = [];
  for (let index = 0; index < maps.length; index += 1) {
    onProgress(index + 1, maps.length, maps[index]);
    const mapType = maps[index];
    entries.push({
      name: `${generator.id}-${mapType}-${width}x${height}-${params.Seed || "seed"}.${extension}`,
      blob: await createTextureBlob(generator, params, output, mimeType, mapType),
    });
    await new Promise((resolve) => setTimeout(resolve, 20));
  }
  const zip = await createZipBlob(entries);
  downloadBlob(zip, `${generator.id}-texture-pack-${width}x${height}-${params.Seed || "seed"}.zip`);
}

function downloadBlob(blob, filename) {
  const link = document.createElement("a");
  link.download = filename;
  link.href = URL.createObjectURL(blob);
  link.click();
  URL.revokeObjectURL(link.href);
}

let crcTable = null;

function getCrcTable() {
  if (crcTable) return crcTable;
  crcTable = new Uint32Array(256);
  for (let i = 0; i < 256; i += 1) {
    let c = i;
    for (let k = 0; k < 8; k += 1) {
      c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    }
    crcTable[i] = c >>> 0;
  }
  return crcTable;
}

function crc32(bytes) {
  const table = getCrcTable();
  let crc = 0xffffffff;
  for (let i = 0; i < bytes.length; i += 1) {
    crc = table[(crc ^ bytes[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function dosDateTime(date = new Date()) {
  const year = Math.max(1980, date.getFullYear());
  const dosTime = (date.getHours() << 11) | (date.getMinutes() << 5) | Math.floor(date.getSeconds() / 2);
  const dosDate = ((year - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate();
  return { dosDate, dosTime };
}

function writeHeader(values, size) {
  const bytes = new Uint8Array(size);
  const view = new DataView(bytes.buffer);
  values.forEach(([offset, type, value]) => {
    if (type === 16) view.setUint16(offset, value, true);
    if (type === 32) view.setUint32(offset, value, true);
  });
  return bytes;
}

async function createZipBlob(entries) {
  const encoder = new TextEncoder();
  const date = dosDateTime();
  const localParts = [];
  const centralParts = [];
  let offset = 0;

  for (const entry of entries) {
    const nameBytes = encoder.encode(entry.name);
    const dataBytes = new Uint8Array(await entry.blob.arrayBuffer());
    const crc = crc32(dataBytes);
    const size = dataBytes.byteLength;
    const localHeader = writeHeader([
      [0, 32, 0x04034b50],
      [4, 16, 20],
      [6, 16, 0x0800],
      [8, 16, 0],
      [10, 16, date.dosTime],
      [12, 16, date.dosDate],
      [14, 32, crc],
      [18, 32, size],
      [22, 32, size],
      [26, 16, nameBytes.length],
      [28, 16, 0],
    ], 30);
    localParts.push(localHeader, nameBytes, dataBytes);

    const centralHeader = writeHeader([
      [0, 32, 0x02014b50],
      [4, 16, 20],
      [6, 16, 20],
      [8, 16, 0x0800],
      [10, 16, 0],
      [12, 16, date.dosTime],
      [14, 16, date.dosDate],
      [16, 32, crc],
      [20, 32, size],
      [24, 32, size],
      [28, 16, nameBytes.length],
      [30, 16, 0],
      [32, 16, 0],
      [34, 16, 0],
      [36, 16, 0],
      [38, 32, 0],
      [42, 32, offset],
    ], 46);
    centralParts.push(centralHeader, nameBytes);
    offset += localHeader.byteLength + nameBytes.byteLength + dataBytes.byteLength;
  }

  const centralSize = centralParts.reduce((total, part) => total + part.byteLength, 0);
  const eocd = writeHeader([
    [0, 32, 0x06054b50],
    [4, 16, 0],
    [6, 16, 0],
    [8, 16, entries.length],
    [10, 16, entries.length],
    [12, 32, centralSize],
    [16, 32, offset],
    [20, 16, 0],
  ], 22);

  return new Blob([...localParts, ...centralParts, eocd], { type: "application/zip" });
}


